import copy
import os
import re
import six
from abc import ABCMeta, abstractmethod
from .exceptions import (IncorrectDefinition, TemplatesNotDefined)


class TemplatesDefinition(object):
    def __init__(self, **kwargs):
        self._params = {}
        self.define(**kwargs)

    def define(self, **kwargs):
        self._params.clear()
        for k, v in kwargs.items():
            if k not in self._keys:
                raise IncorrectDefinition
            self._params[k] = v

    @property
    def params(self):
        return dict(self._params)

    def get_templates_dir(self, templates_root):
        t = self._template.format(**self._params)
        return os.path.join(templates_root, t)


class Templates5G17(TemplatesDefinition):
    _keys = ['option']
    _template = '{option}'


class Templates5G17A(TemplatesDefinition):
    _keys = ['option', 'ueup']
    _template = 'option_{option}/{ueup}_ueup'


class Templates5G18A(Templates5G17A):
    pass


class TemplatesAgent5g(TemplatesDefinition):
    _keys = ['program']
    _template = '{program}'


class Templates5G18A_RCP20(TemplatesDefinition):
    _keys = ['standalone']
    _template = '5G18A{standalone}'

    def define(self, **kwargs):
        is_standalone = kwargs.pop('standalone')
        standalone = "SA" if is_standalone else ""
        super(Templates5G18A_RCP20, self).define(standalone=standalone)


class TemplatesCache(object):
    def __init__(self):
        self._templates = {}

    def define(self, templates_cls, **kwargs):
        assert issubclass(templates_cls, TemplatesDefinition)
        self._templates[templates_cls] = templates_cls(**kwargs)

    def get(self, templates_cls):
        if templates_cls in self._templates:
            return self._templates[templates_cls]
        else:
            raise TemplatesNotDefined


class TemplatesDispatcher(object):
    def __init__(self):
        self._version_pattern = r'[Aa]ddons-(\d+\.\d+)'
        # TODO: it will probably change a lot in future, so maybe move it to
        # seperate file?
        self._addons_mappings = {
            '2.0': Templates5G17,
            '3.0': Templates5G17A,
            '4.0': Templates5G18A,
            '4.1': Templates5G18A,
            '4.11': Templates5G18A_RCP20,
            '4.12': Templates5G18A_RCP20,
            '4.135': TemplatesAgent5g,
            '4.1000': Templates5G18A,
            '4.1001': Templates5G18A,
            '4.1011': Templates5G18A_RCP20,
            '4.1012': Templates5G18A_RCP20,
            '4.2011': Templates5G18A_RCP20,
            '4.2101': Templates5G18A,
            '4.3111': Templates5G18A_RCP20,
            '4.3113': TemplatesAgent5g,
            '4.5133': TemplatesAgent5g,
            '4.6133': TemplatesAgent5g,
            '4.7135': TemplatesAgent5g,
            '4.10001': Templates5G18A,
            '4.10002': Templates5G18A,
            '4.20012': Templates5G18A_RCP20
        }
        self._program_mappings = {
            '5G17': Templates5G17,
            '5G17A': Templates5G17A,
            '5G18A': Templates5G18A,
            '5G18A_RCP20': Templates5G18A_RCP20
        }

    def _get_cls(self, mapping, key, msg):
        if key in mapping:
            return mapping[key]
        else:
            return TemplatesAgent5g

    def get_cls_by_addons(self, addons):
        version = self.read_version(addons)
        msg = 'Addons version {} is not supported!'.format(version)
        return self._get_cls(self._addons_mappings, version, msg)

    def get_cls_by_program(self, program):
        msg = 'Program {} is not supported!'.format(program)
        return self._get_cls(self._program_mappings, program, msg)

    def read_version(self, addons):
        """ Read software version from addons archive filename.
        :param addons: Should be archive filename or path which contains
        archive name.
        """
        patt = re.compile(self._version_pattern)
        match = patt.search(addons)
        return match.group(1) if match and match.lastindex > 0 else None


@six.add_metaclass(ABCMeta)
class Wrappable(object):
    """Wrap/unwrap heat template configuration after reading/before saving to
    omit redundant parameters when using configuration while keeping original
    structure.  """

    @abstractmethod
    def wrap(self):
        pass

    @abstractmethod
    def unwrap(self):
        pass


class SingleTemplate(Wrappable):
    def __init__(self, template):
        self._template = template
        self._main_section = 'parameters'
        self.__saved_template = None

    def __getitem__(self, key):
        return self._template[key]

    def __setitem__(self, key, value):
        self._template[key] = value

    def __delitem__(self, key):
        del self._template[key]

    def __contains__(self, key):
        return key in self._template

    @property
    def data(self):
        return dict(self._template)

    def keys(self):
        return list(self._template.keys())

    def get_value_from_template(self, key):
        """
            Provide information from dictionary created from config_bts.env based on 'key' parameter

            :param key: provide information, which values the dictionary should return

            It returns specified information from dictionary
        """
        if self.__saved_template is None:
            return self._template[key]
        else:
            return self.__saved_template[key]

    def wrap(self):
        self.__saved_template = copy.copy(self._template)
        self._template = self._template[self._main_section]

    def unwrap(self):
        if self.__saved_template is not None:
            template = self.__saved_template
            template[self._main_section] = self._template
            self._template = template
            self.__saved_template = None
        else:
            self._template = {self._main_section: self._template}


class HeatTemplate(object):
    def __init__(self, yaml, env=None):
        self._yaml = yaml
        self._env = env

    @property
    def yaml(self):
        return copy.copy(self._yaml)

    @property
    def env(self):
        return copy.copy(self._env)

    def get_available_keys(self):
        return self.yaml.keys()
